def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the three adjacent nonzero cells that form the pattern at the top.
    start = next(c for c in range(w - 2)
                 if all(grid[0][c + k] != 0 for k in range(3)))
    anchors = {grid[0][start + k]: start + k for k in range(3)}

    for color, col in anchors.items():
        points = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color and not (r == 0 and c == col)]

        # Extend the vertical ray down, stopping at the matching marker if present.
        stop = min((r for r, c in points if r > 0), default=h - 1)
        for r in range(stop + 1):
            out[r][col] = color

        # Connect each matching marker horizontally to the vertical ray.
        for r, c in points:
            if r > 0:
                for x in range(min(c, col), max(c, col) + 1):
                    out[r][x] = color

    return out
